        "Vegetarian" boolean NOT NULL,
        CONSTRAINT "PK_MenuItems" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_MenuItems_Categories_CategoryId" FOREIGN KEY ("CategoryId") REFERENCES "Categories" ("Id") ON DELETE RESTRICT
    );
    END IF;
END $EF$;

DO $EF$
