DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260910035000_IntegrityConstraints') THEN
    ALTER TABLE "Users" ADD CONSTRAINT "CK_User_Role" CHECK ("Role" IN ('Waiter','Kitchen','Cashier','Admin'));
